'use strict';
(()=>{
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem('scolaria:'+key))??fallback}catch{return fallback}},save=(key,value)=>{try{localStorage.setItem('scolaria:'+key,JSON.stringify(value));return true}catch{return false}};
function download(name,text){const u=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
async function copy(el,status){try{await navigator.clipboard.writeText(el.value);status.textContent='Texte copié.'}catch{el.focus();el.select();status.textContent='Texte sélectionné : utilisez la commande Copier.'}}
const gen=$('#generator');let longPrompt='';
gen?.addEventListener('submit',()=>{longPrompt=$('#generated').value});
for(const b of $$('[data-prompt-mode]'))b.addEventListener('click',()=>{const output=$('#generated'),status=$('#generator-status'),mode=b.dataset.promptMode;if(mode==='edit'){output.focus();status.textContent='Modifiez le texte ci-dessus.';return}if(mode==='regenerate'){if(output.value!==longPrompt&&!confirm('Reconstruire depuis le formulaire et remplacer les modifications du texte ?'))return;gen.requestSubmit();return}if(!gen.reportValidity())return;const d=Object.fromEntries(new FormData(gen));if(mode==='short')output.value=`Prépare une activité de ${d.discipline} pour ${d.level} au Maroc, sur ${d.subject}. Objectif : ${d.objective}. Compétence : ${d.skill}. Durée : ${d.minutes} min ; ${d.students} élèves.\nContraintes : ${d.constraints||'Papier et tableau, sans compte élève'}.\nRéponds en ${d.language} : consigne, étapes minutées, production attendue, corrigé séparé et critères. Prévois une variante sans IA. N’utilise aucune donnée personnelle ; signale les faits, sources et hypothèses à vérifier.`;else output.value=longPrompt+'\n\nAPPROFONDIR\nCompare deux démarches possibles et justifie ton choix. Explicite les prérequis, une erreur fréquente et un contre-exemple. Propose un transfert individuel, une aide graduée et un contrôle des biais linguistiques ou culturels. Termine par une liste de points dont la validation dépend de l’enseignant.';status.textContent=mode==='short'?'Version courte prête à relire.':'Version avancée prête à relire.'});
const lab=$('#lab-form');
function buildLab(d,kind){const intro=`SCOLAR·IA — ${lab.closest('main').querySelector('h1').textContent}\nDiscipline : ${d.discipline||'à préciser'} ; niveau : ${d.level||'à préciser'} au Maroc.\nObjectif : ${d.objective||'vérifier la réponse'}.\n`,control='\nCONTRÔLE\nVérifier contenu, niveau, sources, droits et faisabilité. Ne transmettre aucune donnée personnelle. Le résultat reste un brouillon à valider.';
 if(kind==='ameliorer-prompt')return intro+'\nDEMANDE INITIALE\n'+d.text+'\n\nTÂCHE\nTraite la demande en distinguant faits, hypothèses et informations manquantes. Appuie-toi uniquement sur les supports autorisés fournis.\nFORMAT\nObjectif, étapes, exemple, résultat attendu, corrigé séparé et variante sans connexion.\nCRITÈRES\nConserver l’objectif, demander une preuve de compréhension et signaler les limites.'+control;
 if(kind==='quiz')return intro+`\nSUPPORT AUTORISÉ\n${d.text}\n\nTÂCHE À CONFIER À L’OUTIL CHOISI\nÀ partir de ce seul support, propose ${d.questions} questions : connaissance, compréhension puis transfert. Chaque QCM comprend une seule réponse juste et des distracteurs plausibles.\nFORMAT\nVersion élève sans réponse, puis corrigé séparé : réponse, explication, passage du support et erreur visée. Signale toute question impossible à résoudre avec le support. Évite les indices involontaires et répartis les positions des bonnes réponses.`+control;
 if(kind==='activite'){const n=Number(d.minutes),a=Math.round(n*.2),b=Math.round(n*.5),c=n-a-b;return intro+`\nMATÉRIEL\nTableau, papier et support contrôlé par l’enseignant. ${d.text}\n\n1. OBSERVER — ${a} min\nL’enseignant présente un exemple lié à l’objectif ; chaque élève note une première hypothèse. Preuve : une phrase individuelle.\n\n2. COMPARER ET EXPLIQUER — ${b} min\nEn binômes, comparer deux démarches préparées par l’enseignant. Repérer un accord, une différence et une preuve. L’enseignant demande « pourquoi ? » et fournit une aide graduée. Preuve : tableau des arguments.\n\n3. TRANSFÉRER — ${c} min\nRésoudre individuellement une variante et expliquer une vérification. L’enseignant recueille les traces et choisit la remédiation.\n\nÉVALUATION\nExactitude, justification et capacité à utiliser la notion seul.\nVARIANTE SANS IA\nUtiliser deux propositions rédigées par l’enseignant.\nÀ COMPLÉTER AVANT LA SÉANCE\nExemple de départ : …\nDeux démarches : …\nVariante de transfert et corrigé : …`+control;}
 if(kind==='grille')return intro+`\nGRILLE SUR 20 — À ADAPTER\nContexte : ${d.text}\n\nChaque critère vaut 5 points :\n0 : aucune trace exploitable ; 1 : début très incomplet ; 2 : réussite partielle avec erreurs importantes ; 3 : démarche majoritairement correcte ; 4 : réussite justifiée avec une limite mineure ; 5 : réussite précise, autonome et transférable.\n\n1. Compréhension de l’objectif /5\nIndicateur : reformule le problème et identifie les informations utiles.\n2. Exactitude de la production /5\nIndicateur : applique correctement la notion et contrôle les résultats.\n3. Justification et vérification /5\nIndicateur : présente une preuve, un calcul ou une source pertinente et explicite une limite.\n4. Autonomie et retour sur la démarche /5\nIndicateur : explique ses décisions et traite une variante sans aide.\n\nTOTAL : … /20\nAcquis observable : …\nProchaine étape : …\nAides autorisées et déclaration d’usage : …\nLa simple utilisation déclarée d’une IA n’ajoute ni ne retire automatiquement des points.`+control;
 if(kind==='adapter')return intro+'\nRESSOURCE COMMUNE\n'+d.text+'\n\nTROIS DEMANDES À COPIER\n1. AIDE FORTE : conserve exactement l’objectif. Ajoute un lexique, un exemple résolu partiellement et deux questions intermédiaires. Ne donne pas la réponse finale.\n2. AIDE MODÉRÉE : conserve le même objectif. Propose deux indices successifs et une question de vérification.\n3. APPROFONDISSEMENT : conserve le même objectif puis ajoute un contre-exemple, une contrainte et une justification du domaine de validité.\n\nÉPREUVE COMMUNE\nTermine chaque version par la même question de transfert à résoudre individuellement sans aide. Fournis un corrigé séparé et explique ce qui reste identique entre les versions.'+control;
 return 'JOURNAL DE VÉRIFICATION SCOLAR·IA\nRéponse à examiner :\n'+d.text+'\n\nPour chaque affirmation :\nAffirmation exacte : …\nSource primaire trouvée : …\nAuteur et date : …\nPassage qui soutient ou contredit : …\nPortée et limites : …\nVerdict : non vérifié / confirmé dans ce contexte / contredit / opinion.\n\nBIAIS ET INCERTITUDES\nQuels groupes, langues ou points de vue sont absents ? …\nQue manque-t-il pour conclure ? …\n\nAucun verdict automatique n’est produit.';
}
lab?.addEventListener('submit',e=>{e.preventDefault();if(!lab.reportValidity())return;const d=Object.fromEntries(new FormData(lab)),kind=lab.dataset.lab;$('#lab-text').value=buildLab(d,kind);$('#lab-output').hidden=false;$('#lab-status').textContent='Brouillon construit localement. Relisez avant de copier.';$('#lab-analysis').innerHTML=kind==='analyser'?'<p>Ces segments sont découpés mécaniquement, pas reconnus comme vrais ou faux. Choisissez ceux qui nécessitent une preuve.</p><ol>'+d.text.split(/(?<=[.!?؟])\s+|\n+/).filter(Boolean).slice(0,12).map(t=>'<li>'+E(t)+' — <strong>à examiner</strong></li>').join('')+'</ol>':'';$('#lab-text').focus()});
for(const b of $$('[data-lab-action]'))b.addEventListener('click',async()=>{const output=$('#lab-text'),status=$('#lab-status');if(!output.value.trim())return;switch(b.dataset.labAction){case 'copy':await copy(output,status);break;case 'export':download('scolaria-lab-'+lab.dataset.lab+'.txt',output.value);status.textContent='Téléchargement demandé.';break;case 'edit':output.focus();break;case 'save':{const a=read('prompts',[]);if(!Array.isArray(a)){status.textContent='Sauvegarde indisponible.';break}a.unshift({id:crypto.randomUUID(),title:document.querySelector('h1').textContent,text:output.value,date:new Date().toISOString()});status.textContent=save('prompts',a.slice(0,100))?'Sauvegardé dans Mon espace.':'Stockage indisponible : téléchargez le texte.';}}});
if($('#academy-count')||$('[data-academy]'))fetch('/evolution-data.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(({academy})=>{let done=read('academy',[]);if(!Array.isArray(done))done=[];done=done.filter(id=>academy.some(a=>a.id===id));if($('#academy-count')){$('#academy-count').textContent=done.length+' parcours terminé'+(done.length>1?'s':'')+' sur 10';$('#academy-progress').value=done.length;}const form=$('[data-academy]');if(form)form.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;const a=academy.find(a=>a.id===form.dataset.academy),passed=Number(new FormData(form).get('answer'))===a.correct,r=form.querySelector('[data-academy-result]');r.hidden=false;const stored=passed&&save('academy',[...new Set([...done,a.id])]);r.textContent=(passed?stored?'Parcours enregistré. ':'Bonne réponse, mais progression non conservée. ':'À revoir. ')+a.explanation;});}).catch(()=>{if($('#academy-count'))$('#academy-count').textContent='Progression indisponible. Les parcours restent consultables.';});
if($('#maintenance-results')||$('#profile-recommendations'))fetch('/catalogue.json').then(r=>r.json()).then(rows=>{if($('#maintenance-results')){const render=()=>{const mode=$('#maintenance-state').value,today=new Date().toISOString().slice(0,10),found=rows.filter(r=>mode==='all'||mode==='documented'&&r.verifiedAt||mode==='review'&&(r.lifecycleStatus==='review'||r.reviewAfter&&r.reviewAfter<=today));$('#maintenance-count').textContent=found.length+' fiches';$('#maintenance-results').innerHTML=found.map(r=>`<tr><td><a href="/ressources/${E(r.id)}/">${E(r.title)}</a></td><td>${E(r.verifiedAt||'À vérifier')}</td><td>${E(r.reviewAfter||'À planifier')}</td><td>${E(r.reviewEvidence?.scope.join(' ; ')||(r.sourceGrade==='Éditorial'?'Contenu original ; revue éditoriale '+r.editorialReviewedAt:'Portée à documenter'))}</td></tr>`).join('')};$('#maintenance-state').addEventListener('change',render);render();}if($('#profile-recommendations')){const recommend=()=>{const p=read('preferences',{}),found=rows.filter(r=>r.type!=='outil'&&(!p.discipline||r.discipline===p.discipline||r.discipline==='Toutes disciplines')&&(!p.interest||r.skills?.includes(p.interest))).slice(0,4);$('#profile-recommendations').innerHTML='<ul>'+found.map(r=>`<li><a href="/ressources/${E(r.id)}/">${E(r.title)}</a> · ${E(r.discipline)}</li>`).join('')+'</ul>';};recommend();$('#preferences')?.addEventListener('submit',recommend);}}).catch(()=>{});
})();
